For example, modify main.cpp to run the main OpenPLC task on the isolated core. Something like this on the REAL-TIME
INITIALIZATION section in main.cpp should do the job:
//Set process affinity to core 3
cpu_set_t mask;
CPU_ZERO(&mask);
CPU_SET(3, &mask);
if (sched_setaffinity(0, sizeof(mask), &mask) < 0)
{
printf("WARNING: Error setting affinity of main thread\n");
}
if (pthread_setaffinity_np(pthread_self(), sizeof(mask), &mask) < 0)
{
printf("WARNING: Error setting thread affinity of main thread\n");
}
